# Generated by manage.py generate_test_cases.
"""Exercise component uploads using the shared reference-aware upload service."""

from django.core.files.uploadedfile import SimpleUploadedFile

from bloomerp.models import FileNode, FileReference
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestUploadFilesComponent(BloomerpComponentTestCase):
    """Store uploads with optional object references and no physical folder input."""

    view_name = "components_files_upload"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check library/object uploads, authorization, and obsolete placement rejection."""
        customer = self.CustomerModel.objects.first()
        return [
            RequestScenario(
                name="Upload unreferenced content",
                method="POST",
                user=self.admin_user,
                data={"files": SimpleUploadedFile("library.txt", b"bytes")},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        FileNode.objects.filter(
                            name="library.txt", meta__size=5
                        ).exists()
                        and not FileReference.objects.exists()
                    )
                ),
            ),
            RequestScenario(
                name="Upload creates an object reference",
                method="POST",
                user=self.admin_user,
                data={
                    "files": SimpleUploadedFile("object.txt", b"bytes"),
                    "model_label": customer._meta.label,
                    "object_id": str(customer.pk),
                },
                expected=ExpectedResult(
                    response_validators=lambda response: FileReference.objects.filter(
                        file__name="object.txt", object_id=str(customer.pk)
                    ).exists()
                ),
            ),
            RequestScenario(
                name="Deny unauthorized library upload",
                method="POST",
                user=self.normal_user,
                data={"files": SimpleUploadedFile("private.txt", b"bytes")},
                expected=ExpectedResult(
                    status_code=403,
                    response_validators=lambda response: not FileNode.objects.exists(),
                ),
            ),
            RequestScenario(
                name="Reject physical upload placement",
                method="POST",
                user=self.admin_user,
                data={
                    "files": SimpleUploadedFile("bad.txt", b"bytes"),
                    "folder_id": "1",
                },
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=lambda response: not FileNode.objects.exists(),
                ),
            ),
        ]
